  "lennox": {"k1_1": "Hey Ludwig, eine Kippe für mich.", "k1_2": "Hey Ludwig, zwei Kippen für mich.", "k1_3": "Hey Ludwig, drei Kippen für mich.", "k1_4": "Hey Ludwig, vier Kippen für mich.", "k2_1": "Schnell, ich brauch eine Kippe. Ich muss gleich weiter.", "k2_2": "Schnell, ich brauch zwei Kippen. Ich muss gleich weiter.", "k2_3": "Schnell, ich brauch drei Kippen. Ich muss gleich weiter.", "k2_4": "Schnell, ich brauch vier Kippen. Ich muss gleich weiter.", "k3_1": "Chef, einmal eine Kippe bitte!", "k3_2": "Chef, einmal zwei Kippen bitte!", "k3_3": "Chef, einmal drei Kippen bitte!", "k3_4": "Chef, einmal vier Kippen bitte!", "ks_stopf": "Hast du schon Stopfkippen im Angebot?", "ks_aroma": "Hast du schon Aromakippen im Angebot?", "ks_zigarillo": "Hast du schon Zigarillos im Angebot?", "ks_joint": "Hast du schon Joints im Angebot?", "ks_vmango": "Hast du schon Mango-Vapes im Angebot?", "ks_vmenthol": "Hast du schon Menthol-Vapes im Angebot?", "ks_vkirsche": "Hast du schon Kirsch-Vapes im Angebot?", "k_viel": "Mach einfach die Tasche voll, Ludwig!", "dank1": "Perfekt. Genau so!", "dank2": "Danke, Chef. Das wird mal ein Imperium.", "dank3": "Top. Bis nachher!", "weg1": "Dauert zu lange. Nächstes Mal.", "weg2": "Ich hab noch was zu bauen. Bin weg!", "teuer1": "Das ist doch ein Bug in deinem Preis.", "teuer2": "Viel zu teuer. Noch mal neu!", "genervt1": "Nee. Neustart. Ich bin weg.", "zuviel1": "Stopp, das sind viel zu viele.", "wenig1": "Nur so wenig? Na ja, passt.", "hand1": "Deine Taschen sagen was anderes, Ludwig.", "gruss_morgen": "Morgen! Schon online?", "gruss_tag": "Hi Ludwig. Was geht?", "gruss_abend": "Na, Abendschicht?", "gruss_nacht": "Die besten Sachen passieren nachts.", "gruss_r": "Boah, man sieht ja gar nichts mehr bei dir!"},
  "luca": {"k1_1": "Ähm. Ich glaub, eine Kippe.", "k1_2": "Ähm. Ich glaub, zwei Kippen.", "k1_3": "Ähm. Ich glaub, drei Kippen.", "k1_4": "Ähm. Ich glaub, vier Kippen.", "k2_1": "Warte. Was wollte ich. Ach ja, eine Kippe.", "k2_2": "Warte. Was wollte ich. Ach ja, zwei Kippen.", "k2_3": "Warte. Was wollte ich. Ach ja, drei Kippen.", "k2_4": "Warte. Was wollte ich. Ach ja, vier Kippen.", "k3_1": "Luca. Ich bin Luca. Eine Kippe, bitte.", "k3_2": "Luca. Ich bin Luca. Zwei Kippen, bitte.", "k3_3": "Luca. Ich bin Luca. Drei Kippen, bitte.", "k3_4": "Luca. Ich bin Luca. Vier Kippen, bitte.", "ks_stopf": "Gibt es bei dir eigentlich Stopfkippen?", "ks_aroma": "Gibt es bei dir eigentlich Aromakippen?", "ks_zigarillo": "Gibt es bei dir eigentlich Zigarillos?", "ks_joint": "Gibt es bei dir eigentlich Joints?", "ks_vmango": "Gibt es bei dir eigentlich Mango-Vapes?", "ks_vmenthol": "Gibt es bei dir eigentlich Menthol-Vapes?", "ks_vkirsche": "Gibt es bei dir eigentlich Kirsch-Vapes?", "k_viel": "Viele. Dann kann ich länger schlafen.", "dank1": "Danke dir.", "dank2": "Schön. Gute Nacht.", "dank3": "Oh, schon fertig? Danke.", "weg1": "Ich bin fast eingeschlafen. Ich gehe.", "weg2": "Vielleicht morgen.", "teuer1": "Träume ich? So teuer?", "teuer2": "Das ist zu viel Geld für so wenig Schlaf.", "genervt1": "Jetzt bin ich wach. Na toll. Tschüss.", "zuviel1": "Das kann ich gar nicht alles tragen.", "wenig1": "Reicht bis zum nächsten Nickerchen.", "hand1": "Entweder ich seh doppelt, oder dir fehlen welche.", "gruss_morgen": "Ist heute Montag?", "gruss_tag": "Ich hab gerade Mittagsschlaf gemacht.", "gruss_abend": "Bald Bettzeit.", "gruss_nacht": "Schlafwandeln bringt mich immer hierher.", "gruss_r": "Ist das eine Wolke? Ich leg mich rein."},
  "manni": {"k1_1": "Glück auf, Jung! Eine Kippe!", "k1_2": "Glück auf, Jung! Zwei Kippen!", "k1_3": "Glück auf, Jung! Drei Kippen!", "k1_4": "Glück auf, Jung! Vier Kippen!", "k2_1": "Manni hat Pause. Eine Kippe, aber flott.", "k2_2": "Manni hat Pause. Zwei Kippen, aber flott.", "k2_3": "Manni hat Pause. Drei Kippen, aber flott.", "k2_4": "Manni hat Pause. Vier Kippen, aber flott.", "k3_1": "Mahlzeit! Mach mal eine Kippe.", "k3_2": "Mahlzeit! Mach mal zwei Kippen.", "k3_3": "Mahlzeit! Mach mal drei Kippen.", "k3_4": "Mahlzeit! Mach mal vier Kippen.", "ks_stopf": "Sach mal, Jung, haste auch Stopfkippen?", "ks_aroma": "Sach mal, Jung, haste auch Aromakippen?", "ks_zigarillo": "Sach mal, Jung, haste auch Zigarillos?", "ks_joint": "Sach mal, Jung, haste auch Joints?", "ks_vmango": "Sach mal, Jung, haste auch Mango-Vapes?", "ks_vmenthol": "Sach mal, Jung, haste auch Menthol-Vapes?", "ks_vkirsche": "Sach mal, Jung, haste auch Kirsch-Vapes?", "k_viel": "Für die ganze Baustelle. Schaufel voll!", "dank1": "Besten Dank, Junge.", "dank2": "Wie gemauert. Danke.", "dank3": "So, weiter geht's. Danke!", "weg1": "Der Beton wird hart. Ich muss!", "weg2": "Pause vorbei. Tschüssikowski.", "teuer1": "Dafür verputz ich dir das ganze Haus!", "teuer2": "Bei dem Preis fällt mir der Helm runter.", "genervt1": "Jetzt is aber Schicht im Schacht!", "zuviel1": "Ich brauch keinen Lastwagen voll.", "wenig1": "Dat is wenig. Aber gut.", "hand1": "Da fehlt Material, Jung!", "gruss_morgen": "Moin! Seit fünf auf der Baustelle!", "gruss_tag": "Mahlzeit!", "gruss_abend": "Feierabend, endlich.", "gruss_nacht": "Nachtschicht. Die zahlen besser.", "gruss_r": "Bei dir staubt's schlimmer als beim Abriss!"},
  "mia": {"k1_1": "Huhu, Ludwig! Ich hätte gern eine Kippe.", "k1_2": "Huhu, Ludwig! Ich hätte gern zwei Kippen.", "k1_3": "Huhu, Ludwig! Ich hätte gern drei Kippen.", "k1_4": "Huhu, Ludwig! Ich hätte gern vier Kippen.", "k2_1": "Kannst du mir bitte eine Kippe geben?", "k2_2": "Kannst du mir bitte zwei Kippen geben?", "k2_3": "Kannst du mir bitte drei Kippen geben?", "k2_4": "Kannst du mir bitte vier Kippen geben?", "k3_1": "Ich bin's, Mia! Eine Kippe, ja?", "k3_2": "Ich bin's, Mia! Zwei Kippen, ja?", "k3_3": "Ich bin's, Mia! Drei Kippen, ja?", "k3_4": "Ich bin's, Mia! Vier Kippen, ja?", "ks_stopf": "Oh, hast du auch Stopfkippen?", "ks_aroma": "Oh, hast du auch Aromakippen?", "ks_zigarillo": "Oh, hast du auch Zigarillos?", "ks_joint": "Oh, hast du auch Joints?", "ks_vmango": "Oh, hast du auch Mango-Vapes?", "ks_vmenthol": "Oh, hast du auch Menthol-Vapes?", "ks_vkirsche": "Oh, hast du auch Kirsch-Vapes?", "k_viel": "Ich hole für alle! Ganz, ganz viele bitte.", "dank1": "Du bist ein Schatz!", "dank2": "Danke, danke, danke!", "dank3": "Super lieb. Bis dann!", "weg1": "Schade, dann eben nicht.", "weg2": "Ich frier mir hier die Nase ab. Tschüss!", "teuer1": "Was? So viel Taschengeld hab ich gar nicht!", "teuer2": "Och komm, ein bisschen billiger!", "genervt1": "Du bist echt gemein, Ludwig!", "zuviel1": "Hilfe, so viele brauche ich nicht.", "wenig1": "Mehr hast du nicht? Okay.", "hand1": "Du hast doch gar nicht genug dabei, du Schussel.", "gruss_morgen": "Guten Morgen, Sonnenschein!", "gruss_tag": "Huhu! Ist das schön draußen!", "gruss_abend": "Hallöchen, noch jemand wach?", "gruss_nacht": "Ludwig? Ich bin ganz leise.", "gruss_r": "Iih, das riecht ja furchtbar bei dir!"},
